use vstd::prelude::*;

verus! {

fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
    ensures
        // The output length is twice the input length
        result.len() == 2 * arr.len(),
        // For each index k in the original, we have elem at 2*k and arr[k] at 2*k+1
        forall |k: usize| k < arr.len() ==>
            result.get(2*k) == Some(&elem) &&
            result.get(2*k + 1) == arr.get(k),
{
    let mut result: Vec<i32> = Vec::new();
    // Pre-allocate space to avoid reallocation
    result.reserve(2 * arr.len());
    let mut i: usize = 0;
    while i < arr.len()
        invariant
            // We never advance past the end of `arr`
            i <= arr.len(),
            // We have already inserted `elem` and `arr[j]` for each j < i
            result.len() == 2 * i,
            // And those are exactly the first 2*i elements of `result`
            forall |j: usize| j < i ==>
                result.get(2*j) == Some(&elem) &&
                result.get(2*j + 1) == arr.get(j),
        decreases arr.len() - i,
    {
        // Insert `elem` before arr[i]
        result.push(elem);
        result.push(arr[i]);
        i += 1;
    }
    result
}

}

fn main() {
    // Example usage
    let v = vec![10, 20, 30];
    let out = insert_before_each(&v, 7);
    assert!(out == vec![7, 10, 7, 20, 7, 30]);
}